if mibBuilder.loadTexts: ciscoIdslLineMIB.setDescription('This MIB module describes IDSL (ISDN Digital Line Subscriber)\n        line interfaces.  The structure of this module resembles that\n        of the ADSL-LINE-MIB (RFC-2662).  Observe that the tables in\n        this module do not necessarily extend the tables defined by the\n        ADSL-LINE-MIB.  Currently, only those tables that contain\n        configuration information extend the profile tables defined by\n        the ADSL-LINE-MIB.  This allows the management client to define\n        xDSL configuration profiles that apply across all xDSL modems,\n        independent of the technology being utilized by the modem.\n\n        *** ABBREVIATIONS, ACRONYMS, AND SYMBOLS ***\n\n        ADSL - Asymmetric Digital Subscriber Line.\n\n        ATM - Asynchronous Transfer Mode.\n        \n        BRITE - Basic Rate Interface Terminal Extender.\n\n        CV - Coding Violation.\n\n        DLC - Data Link Connection.\n\n        DSL - Digital Subscriber Line.\n\n        ES - Error Second.\n\n        IDSL - IDSN Digital Subscriber Loop.\n\n        ITU-C - IDSL Transceiver Unit, Central Office end.\n\n        ITU-R - IDSL Transceiver Unit, Remote terminal end.\n\n        LMI - Link Management Interface.\n\n        LOF - Loss Of Frame.\n\n        LOS - Loss Of Signal.\n        \n        NT - Network Terminator.\n\n        PPP - Point-to-Point Protocol.\n        \n        PPPoA - PPP over ATM.\n\n        SES - Severely Errored Second.\n\n        *** DEFINITIONS ***\n\n        CODING VIOLATION\n            A coding violation occurs when the incoming signal exhibits\n            a CRC anomaly.\n\n        DOWNSTREAM\n            The flow of data in the direction from the ITU-C to ITU-R.\n                      \n        ERRORED SECOND\n            A second with one or more coding violations.\n\n        LINE RATE\n            The total data rate supported by a line.  Observe that the\n            payload rate is equal the line rate for the earliest\n            implementations of IDSL.  However, the payload rate maybe\n            less than the line rate for future implementations.\n\n        SEVERELY ERRORED SECOND\n            A second with 3 or more coding violations.\n                          \n        UPSTREAM\n            The flow of data in the direction from the ATU-R to ATU-C.')
class IdslPerfTimeElapsed(TextualConvention, Gauge32):
    description = "The number of seconds that have elapsed since the beginning of\n        the current measurement period.  If, for some reason, such as an\n        adjustment in the system's time-of-day clock, the current\n        interval exceeds the maximum value, the agent will return the\n        maximum value."
    status = 'current'

class IdslPerfCurrDayCount(TextualConvention, Gauge32):
    description = "A counter associated with interval performance measurements in\n        a current 1-day (24 hour) measurement interval.\n\n        The value of this counter starts at zero at the beginning of an\n        interval and increases when associated events occur, until the\n        end of the 1-day interval.  At that time, the agent stores the\n        value of the counter in the previous 1-day history interval,\n        if available, and resets the value of the counter to zero.\n\n        In the case where the agent has no valid data available for this\n        interval, the corresponding object instance is not available.\n        In this case, the agent will respond with the appropriate error\n        indicating that the instance does not exist; that is,\n        'noSuchName' in response to a SNMPv1 get request, and\n        'noSuchInstance' in response to a SNMPv2 get request."
    status = 'current'

class IdslPerfPrevDayCount(TextualConvention, Gauge32):
    description = "A counter associated with interval performance measurements\n        during the most previous 1-day (24 hour) measurement interval.\n        The value of this counter is equal to the current day counter\n        at the end of its most recent interval.\n\n        In the case where the agent has no valid data available for this\n        interval, the corresponding object instance is not available.\n        In this case, the agent will respond with the appropriate error\n        indicating that the instance does not exist; that is,\n        'noSuchName' in response to a SNMPv1 get request, and\n        'noSuchInstance' in response to a SNMPv2 get request."
    status = 'current'

